pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, address caller) public {
        // Ensure caller is not zero address to avoid revert on call
        vm.assume(caller != address(0));
        // Precondition: never call SetMinSum, so MinSum stays 0
        // Fund the contract so it can pay out (optional, but realistic)
        vm.deal(address(c), am);
        // Give caller some ether to put (optional, not needed for Collect call)
        vm.deal(caller, am);
        vm.prank(caller);
        // Try calling Collect(am) – it may revert or succeed
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));
        if (success) {
            // If Collect succeeded, MinSum must still be 0 (default)
            assertTrue(c.MinSum() == 0, "MinSum should remain 0");
        } else {
            // If it reverted, no state change occurred; still check MinSum unchanged
            assertTrue(c.MinSum() == 0, "MinSum should remain 0 after revert");
        }
    }
}

