pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 deposit, uint256 lockTime, uint256 withdrawAmount) public {
        vm.assume(sender != address(0));
        vm.assume(deposit > 0 && deposit < 1e30);
        vm.assume(lockTime < 1e12);
        vm.assume(withdrawAmount <= deposit);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(1_000_000); // some non-zero minimum

        // Deposit funds
        vm.deal(sender, deposit);
        vm.prank(sender);
        c.Put{value: deposit}(lockTime);

        // Record state before collect
        uint256 balanceBefore = c.Acc(sender).balance;
        uint256 minSum = c.MinSum();

        // Attempt collect
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));

        // Rule: If balanceBefore >= minSum AND balanceBefore >= withdrawAmount AND block.timestamp > unlockTime, then success is true
        // But we cannot read unlockTime directly because Acc mapping returns a struct; we check if success implies balance decreased
        if (success) {
            uint256 balanceAfter = c.Acc(sender).balance;
            assertTrue(balanceAfter < balanceBefore, "Collect should reduce balance");
        }
    }
}

