        collectAmount = bound(collectAmount, 0, putValue);

        // Initialize and set up the contract
        c.SetMinSum(0);
        if (logAddr != address(0)) {
            c.SetLogFile(logAddr);
        }
        c.Initialized();

        // Put some ether
        vm.deal(address(this), putValue);
        c.Put{value: putValue}(lockTime);

        // Advance time past unlockTime
        vm.warp(block.timestamp + lockTime + 1);

        // Get the Log address before Collect
        address logBefore;
        try c.Log() returns (address l) {
            logBefore = l;
        } catch {
            logBefore = address(0);
        }

        // Call Collect
        c.Collect(collectAmount);

        // Get the Log address after Collect
        address logAfter;
        try c.Log() returns (address l) {
            logAfter = l;
        } catch {
            logAfter = address(0);
        }

        // Assert that Log is unchanged by Collect
        assertTrue(logBefore == logAfter, "Log state should not be changed by Collect");
