pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am, uint256 _lockTime, uint256 _minSum, uint256 _putValue) public {
        // Bound inputs to reasonable ranges
        _am = bound(_am, 0, 100 ether);
        _lockTime = bound(_lockTime, 0, 365 days);
        _minSum = bound(_minSum, 0, 10 ether);
        _putValue = bound(_putValue, 0, 100 ether);

        // Set up the contract
        c.SetMinSum(_minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Fund the test contract and put some value
        vm.deal(address(this), _putValue);
        c.Put{value: _putValue}(_lockTime);

        // Get the length before Collect
        (uint256 lenBefore, ) = _getLogLength();

        // Try Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        // Get the length after Collect (only possible if Log is addressable)
        (uint256 lenAfter, ) = _getLogLength();

        // The rule: if Collect was successful, the History length must have increased
        assertTrue(!success || lenAfter > lenBefore);
    }

    function _getLogLength() private view returns (uint256, bool) {
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("Log()"));
        if (!ok || data.length == 0) return (0, false);
        address logAddr = abi.decode(data, (address));
        if (logAddr == address(0)) return (0, false);
        (ok, data) = logAddr.staticcall(abi.encodeWithSignature("HistoryLength()"));
        if (!ok || data.length == 0) return (0, false);
        return (abi.decode(data, (uint256)), true);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

